    var osat = m.slice(7).split('|');
    storeValue('siirto', { id: osat[0], uusi: osat[1] }).then(function(){
      return haeStatusvaihto.run();
    }).then(function(d){
      var r = (d && d[0]) || {};
      if (r.sama) { showAlert('Työ on jo tilassa ' + (r.uusi_status || ''), 'warning'); return; }
      showModal('siirtoModal');
    }).catch(function(e){ showAlert('Tarkistus epäonnistui: ' + ((e && e.message) ? e.message : e), 'error'); });
  }
})() }}

