{{ (function(){
  var rows = (SelectQuery.data || []);
  var sarakkeet = [
    ["uusi","Uusi"], ["tarjous_lahetetty","Tarjous lähetetty"], ["tilaus_vastaanotettu","Tilaus vastaanotettu"],
    ["suunnittelussa","Suunnittelussa"], ["tuotannossa","Tuotannossa"], ["odottaa_asennusta","Odottaa asennusta"],
    ["valmis","Valmis"], ["toimitettu","Toimitettu"], ["laskutettu","Laskutettu"]
  ];
  var varit = { 0: "#B4232A", 1: "#DC2626", 2: "#B45309", 3: "#1D4ED8" };
  var esc = function(s){ return String(s == null ? "" : s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); };
  var jono = rows.slice().sort(function(a,b){
    var ta = (a.kiire_taso == null ? 9 : Number(a.kiire_taso)), tb = (b.kiire_taso == null ? 9 : Number(b.kiire_taso));
    if (ta !== tb) { return ta - tb; }
    return Number(b.kiire_odotus || 0) - Number(a.kiire_odotus || 0);
  });
  var html = "";
  for (var i = 0; i < sarakkeet.length; i++) {
    var koodi = sarakkeet[i][0], nimi = sarakkeet[i][1];
    var omat = jono.filter(function(r){ return r.status === koodi; });
    var kortit = omat.map(function(r){
      var vari = varit[r.kiire_taso] || "#9CA3AF";
      var merkit = [];
      if (r.uusi_viesti_suljettuun) { merkit.push("Uusi viesti"); }
      else if (r.odottaa_meilta) { merkit.push("Odottaa meitä"); }
      if (r.valmistumispaiva) { merkit.push("Valmis " + moment(r.valmistumispaiva).format("D.M.")); }
      if (r.omistaja && r.omistaja !== "Ei vastuuhenkilöä") { merkit.push(r.omistaja); }
      var m = merkit.length ? "<div class=\"m\">" + esc(merkit.join(" · ")) + "</div>" : "";
      return "<div class=\"c\" style=\"border-left-color:" + vari + "\" data-id=\"" + esc(r.id) + "\">"
           + "<div class=\"t\">" + esc(r.tp_numero) + "</div>"
           + "<div class=\"y\">" + esc(r.yritys || r.asiakas || "") + "</div>"
           + "<div class=\"a\">" + esc(r.aihe || "") + "</div>" + m + "</div>";
    }).join("");
    if (!kortit) { kortit = "<div class=\"e\">–</div>"; }
    html += "<div class=\"col\" data-status=\"" + koodi + "\"><div class=\"h\"><span>" + nimi + "</span><span class=\"n\">" + omat.length + "</span></div><div class=\"list\">" + kortit + "</div></div>";
  }
  var css = "html,body{height:100%;margin:0;overflow:hidden}body{font-family:-apple-system,Segoe UI,Roboto,Helvetica,sans-serif;font-size:12px;color:#1f2937;background:transparent}body.raahaa{user-select:none;cursor:grabbing}.w{display:flex;gap:8px;padding:2px;height:100%;box-sizing:border-box;overflow-x:auto;overflow-y:hidden}.col{flex:0 0 236px;display:flex;flex-direction:column;background:#f3f4f6;border-radius:8px;padding:6px;box-sizing:border-box;height:100%;overflow:hidden;border:2px solid transparent}.col.yli{background:#eef2ff;border-color:#6366f1;border-style:dashed}.h{font-weight:600;font-size:12px;color:#374151;padding:2px 4px 6px;display:flex;justify-content:space-between;align-items:baseline;flex:0 0 auto}.n{color:#6b7280;font-weight:600}.list{overflow-y:auto;flex:1 1 auto;min-height:0}.c{background:#fff;border:1px solid #e5e7eb;border-left:4px solid #9CA3AF;border-radius:6px;padding:6px 8px;margin-bottom:6px;cursor:grab}.c:hover{border-color:#9ca3af;background:#f9fafb}.c.drag{opacity:.35}.haamu{position:fixed;pointer-events:none;width:214px;opacity:.9;box-shadow:0 8px 18px rgba(0,0,0,.22);z-index:9;margin:0}.t{font-weight:600;font-size:12px}.y{color:#374151;font-size:11px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.a{color:#6b7280;font-size:11px;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.m{font-size:10px;color:#6b7280;margin-top:4px}.e{color:#c7cbd1;text-align:center;padding:10px 0;font-size:11px}";
  var js = "var drag=null, haamu=null, x0=0, y0=0, liikkui=false;function siivoa(){var k=document.querySelectorAll(\".col\");for(var i=0;i<k.length;i++){k[i].classList.remove(\"yli\");}}function sarake(x,y){var el=document.elementFromPoint(x,y);return (el&&el.closest)?el.closest(\"[data-status]\"):null;}function lopeta(){if(!drag){return;}drag.el.classList.remove(\"drag\");document.body.classList.remove(\"raahaa\");if(haamu){haamu.parentNode.removeChild(haamu);haamu=null;}siivoa();drag=null;liikkui=false;}document.addEventListener(\"mousedown\",function(e){if(e.button!==0){return;}var c=e.target.closest(\"[data-id]\");if(!c){return;}drag={el:c,id:c.getAttribute(\"data-id\")};x0=e.clientX;y0=e.clientY;liikkui=false;e.preventDefault();});document.addEventListener(\"mousemove\",function(e){if(!drag){return;}if(!liikkui){if(Math.abs(e.clientX-x0)+Math.abs(e.clientY-y0)<6){return;}liikkui=true;drag.el.classList.add(\"drag\");document.body.classList.add(\"raahaa\");haamu=drag.el.cloneNode(true);haamu.classList.remove(\"drag\");haamu.classList.add(\"haamu\");document.body.appendChild(haamu);}haamu.style.left=(e.clientX+10)+\"px\";haamu.style.top=(e.clientY+10)+\"px\";siivoa();var col=sarake(e.clientX,e.clientY);if(col){col.classList.add(\"yli\");}});document.addEventListener(\"mouseup\",function(e){if(!drag){return;}var id=drag.id, oli=liikkui;var col=sarake(e.clientX,e.clientY);lopeta();if(oli){if(col){parent.postMessage(\"siirra:\"+id+\"|\"+col.getAttribute(\"data-status\"),\"*\");}}else{parent.postMessage(\"tyo:\"+id,\"*\");}});document.addEventListener(\"mouseleave\",function(){lopeta();});";
  return "<html><head><meta charset=\"utf-8\"><style>" + css + "</style></head><body><div class=\"w\">" + html + "</div><script>" + js + "<\/script></body></html>";
})() }}
